INSERT INTO announcements (id, title, content, type, is_published, publish_date, expiry_date, created_by, created_at, updated_at) VALUES (1,'Summer Vacation Notice','School will remain closed from 1st June to 15th August 2025 for summer vacation.','holiday',1,'2025-05-20',NULL,1,'2026-06-19 15:50:58','2026-06-19 15:50:58'),(2,'Admission Open 2025-26','Admissions are open for all classes. Visit school office between 8 AM to 2 PM.','general',1,'2025-04-01',NULL,1,'2026-06-19 15:50:58','2026-06-19 15:50:58'),(3,'Annual Result Day','Annual result ceremony will be held on 25th March 2025 at school auditorium.','event',1,'2025-03-10',NULL,1,'2026-06-19 15:50:58','2026-06-19 15:50:58'),(4,'Sports Week','Inter-house sports week starting from 10th February 2025. All students must participate.','event',1,'2025-02-01',NULL,1,'2026-06-19 15:50:58','2026-06-19 15:50:58'),(5,'Fee Reminder','Please clear pending fees before 15th of this month to avoid inconvenience.','urgent',1,'2025-06-01',NULL,1,'2026-06-19 15:50:58','2026-06-19 15:50:58');

