INSERT INTO news (id, title, summary, content, image_url, is_published, publish_date, created_by, created_at) VALUES (1,'Science Fair 2025','Students showcased innovative projects at the annual science fair.','Our students participated enthusiastically in the science fair with projects on renewable energy, water conservation, and robotics.',NULL,1,'2025-03-15',1,'2026-06-19 15:50:58'),(2,'Debating Competition','Class 9 student won district level English debating competition.','We are proud to announce that our student secured first position in the district English debating competition.',NULL,1,'2025-02-20',1,'2026-06-19 15:50:58'),(3,'New Computer Lab','State-of-the-art computer lab inaugurated for senior classes.','A new computer lab with 25 systems has been inaugurated to enhance IT education.',NULL,1,'2025-01-10',1,'2026-06-19 15:50:58');

