INSERT INTO school_settings (id, setting_key, setting_value, updated_at) VALUES (1,'school_name','Nayab English Grammar High School, Mirwah Gorchani','2026-06-19 15:50:57'),(2,'school_description','Nayab English Grammar High School, Mirwah Gorchani is a Platform For Lifelong Learners. We provide quality English-medium education in rural Sindh, nurturing students with academic excellence, discipline, moral values, and active participation in school functions and community events.','2026-09-11 12:20:14'),(3,'address','Mirwah Gorchani, District Mirpur Khas, Sindh, Pakistan','2026-09-27 20:21:36'),(4,'phone','03043021844 / 03332867412','2026-09-27 20:21:35'),(5,'email','nayabhtsmirwah@gmail.com','2026-09-27 20:21:35'),(6,'principal_name','Miss Rukhsana Ghulam Murtza Arain','2026-09-27 20:21:35'),(7,'established_year','2005','2026-06-19 15:50:57'),(8,'map_embed','https://www.google.com/maps?q=Nayab+English+Grammar+High+School+Mirwah+Gorchani&output=embed','2026-09-11 12:20:14'),(9,'hero_title','Welcome to Nayab English Grammar High School','2026-06-19 15:50:57'),(10,'hero_subtitle','A Platform For Lifelong Learners — Mirwah Gorchani','2026-09-11 12:20:14'),(11,'principal_message','Welcome to Nayab English Grammar High School, Mirwah Gorchani. We believe every child is a lifelong learner. Our dedicated team provides quality English-medium education, strong character building, and a bright future for every student in our community.','2026-09-11 12:20:14'),(12,'vision','To be a leading English-medium institution in Mirwah Gorchani and rural Sindh, producing confident lifelong learners.','2026-09-11 12:20:14'),(13,'mission','To develop knowledgeable, disciplined, and morally upright students through innovative teaching, co-curricular activities, and strong community engagement.','2026-09-11 12:20:14'),(14,'history','Nayab English Grammar High School serves the community of Mirwah Gorchani, District Mirpurkhas. The school actively shares student achievements, annual functions, independence day celebrations, and daily school life through its official Instagram @nayab.h.s.mirwah and Facebook page Nayab English Grammar High School Mirwah Gorchani.','2026-09-11 12:20:14'),(16,'short_name','Nayab H.S Mirwah','2026-09-11 12:20:14'),(17,'tagline','A Platform For Lifelong Learners','2026-09-11 12:20:14'),(23,'academic_session','2025-2026','2026-09-11 12:20:14'),(25,'instagram_url','https://www.instagram.com/nayab.h.s.mirwah/','2026-09-11 12:20:14'),(26,'facebook_url','https://www.facebook.com/NayabEnglishGrammarHighSchoolMirwahGorchani','2026-09-11 12:20:14'),(27,'facebook_profile_url','https://www.facebook.com/nayab.h.s.mirwah','2026-09-11 12:20:14'),(28,'facebook_page_name','Nayab H.S Mirwah','2026-09-27 20:21:36'),(29,'facebook_profile_name','Nayab.h.s.Mirwah','2026-09-27 20:21:36'),(30,'whatsapp_url','https://whatsapp.com/channel/0029VaHZXU1I1rcaNdi9412C','2026-09-11 12:20:14'),(31,'logo_url','/uploads/branding/1790522971061-429151227.jpg','2026-09-27 20:29:31'),(32,'school_photo_url','/uploads/branding/school-banner.svg','2026-09-11 12:21:38'),(39,'data_source','Official Instagram @nayab.h.s.mirwah + Facebook Nayab English Grammar High School Mirwah Gorchani','2026-09-11 12:20:14'),(119,'fee_structure','Nursery to KG1: Rs. 2,000/month
KG2 to Class 8: Rs. 1,800/month
Class 9 & 10: Rs. 2,500/month','2026-09-11 20:05:44'),(174,'school_timing','Monday – Saturday: 8:00 AM – 2:00 PM | Office: 8:00 AM – 1:00 PM','2026-09-11 20:31:30'),(219,'exam_controller_name','Miss Rukhsana Ghulam Murtza Arain','2026-09-27 20:21:36'),(220,'principal_stamp_url','','2026-09-13 13:15:59'),(272,'matric_pass_rate','99.9','2026-09-27 20:21:35');

