INSERT INTO website_content (id, page_key, section_key, title, content, image_url, sort_order, is_active, updated_by, updated_at) VALUES (1,'home','intro','About Our School','[PLACEHOLDER] Nayab English Grammar High School provides quality English-medium education in Mirwah Gorchani. We focus on academic excellence, character building, and extracurricular activities.',NULL,0,1,NULL,'2026-06-19 15:50:58'),(2,'home','facilities','Our Facilities','Modern classrooms, science lab, computer lab, library, playground, and safe transport facility.',NULL,0,1,NULL,'2026-06-19 15:50:58'),(3,'about','facilities','School Facilities','• Spacious Classrooms
• Science Laboratory
• Computer Lab
• Library
• Playground
• Clean Drinking Water
• CCTV Security',NULL,0,1,NULL,'2026-06-19 15:50:58'),(4,'admissions','requirements','Admission Requirements','• Birth Certificate
• Previous School Result (if applicable)
• 2 Passport Size Photos
• B-Form / CNIC Copy
• Parent/Guardian CNIC Copy',NULL,0,1,NULL,'2026-06-19 15:50:58'),(5,'admissions','fees','Fee Structure','Play Group to Class 5: Rs. 2,500/month
Class 6 to 8: Rs. 3,000/month
Class 9 to 10: Rs. 3,500/month
Admission Fee: Rs. 5,000 (one time)',NULL,0,1,NULL,'2026-06-19 15:50:58');

